# Lo que impide aprobar sale de una lista fija (faltaParaAprobar) unida con
# ", ", en el mismo orden siempre: se generan todas las combinaciones.
_FALTA = [("the customer", "el cliente", "le client"),
          ("the part number", "el número de parte", "la référence"),
          ("at least one quantity", "al menos una cantidad", "au moins une quantité"),
          ("the weight per piece", "el peso por pieza", "le poids par pièce"),
          ("a routing", "una ruta", "une gamme")]
# Y lo que el plano no trajo al leerlo (PN, Description, Revision).
_SIN_PLANO = [("PN", "PN", "PN"), ("Description", "Descripción", "Description"),
              ("Revision", "Revisión", "Indice")]


def _combinaciones(lista):
    for m in range(1, 1 << len(lista)):
        elegidos = [x for i, x in enumerate(lista) if m >> i & 1]
        yield tuple(", ".join(x[k] for x in elegidos) for k in range(3))


for _en, _es, _fr in _combinaciones(_FALTA):
    _V7["Needs %s before it can be approved." % _en] = (
        "Falta %s para poder aprobarla." % _es, "Il manque %s pour pouvoir l’approuver." % _fr)
    _V7["Cannot approve yet — missing %s." % _en] = (
        "Todavía no se puede aprobar: falta %s." % _es, "Pas encore approuvable : il manque %s." % _fr)
_V7["Cannot approve yet — missing no quote open."] = (
    "Todavía no se puede aprobar: no hay cotización abierta.", "Pas encore approuvable : aucun devis ouvert.")
for _en, _es, _fr in _combinaciones(_SIN_PLANO):
    _V7["Drawing did not give: %s — fill manually (yellow fields)." % _en] = (
        "El plano no trajo: %s — llénalo a mano (campos amarillos)." % _es,
        "Le plan ne donne pas : %s — à remplir à la main (champs jaunes)." % _fr)
# El estado de la barra inferior: "APPROVED · PO RECEIVED" y compañía.
for _st in ("APPROVED", "SUPERSEDED"):
    for _oc in ("PO RECEIVED", "LOST", "NO RECEPTION"):
        _V7["%s · %s" % (_st, _oc)] = tuple("%s · %s" % (_V7[_st][k], _V7[_oc][k]) for k in range(2))

_REPETIDAS = sorted(set(_V7) & set(D))
assert not _REPETIDAS, "claves de la calculadora de precios que ya existían: %r" % _REPETIDAS
D.update(_V7)

