PLANTILLAS += [
 (r"^capture customer, PN, family, drawing revision \(per PN\), lead time\. Optional AI drawing read fills wire Ø, material, PN, revision\. Wire Ø ≥ (.+)\" \(15 mm\) is never feasible\.$",
  r'captura cliente, PN, familia, revisión del plano (por PN), plazo de entrega. La lectura opcional del plano con IA llena Ø de alambre, material, PN y revisión. Un Ø de alambre ≥ \1" (15 mm) nunca es factible.',
  r'saisir client, PN, famille, indice du plan (par PN), délai. La lecture IA facultative du plan remplit Ø du fil, matière, PN, indice. Un Ø de fil ≥ \1" (15 mm) n’est jamais faisable.'),
 (r"^, never below the ISC floor of (\$[\d,]+) per job \+ (\$[\d,]+) per extra operation\. A manual Price Override accepts any value but is flagged\. Contribution defaults to (.+)% \(editable per quote and per tier\)\. Overheads follow the ladder (.+)% by number of operations \(1/2/3/4\+\), (.+)% when subcontracting is involved, overridable per PN and per tier\. HQ = (.+)% of sell\. Commission = (.+)% \(Nic only\)\.$",
  r", nunca por debajo del piso ISC de \1 por trabajo + \2 por operación adicional. Un precio manual acepta cualquier valor pero levanta alerta. La contribución por defecto es \3% (editable por cotización y por tramo). Los gastos generales siguen la escala \4% según el número de operaciones (1/2/3/4+), \5% cuando hay subcontratación, editable por PN y por tramo. HQ = \6% de la venta. Comisión = \7% (sólo Nic).",
  r", jamais sous le plancher ISC de \1 par OF + \2 par opération supplémentaire. Un prix forcé accepte toute valeur mais lève une alerte. La contribution par défaut est de \3 % (modifiable par devis et par palier). Les frais généraux suivent le barème \4 % selon le nombre d’opérations (1/2/3/4+), \5 % en cas de sous-traitance, modifiable par PN et par palier. HQ = \6 % de la vente. Commission = \7 % (Nic uniquement)."),
 (r"^start quantity = order qty ÷ cumulative yield \(scrap per operation, default (.+)%\); lb to buy = MAX\(needed lb, MOQ lb\); cost = lb × \(base \+ surcharge \+ transport \$/lb\) ÷ qty, \+(.+)% markup\.$",
  r"cantidad de arranque = cant. del pedido ÷ rendimiento acumulado (merma por operación, por defecto \1%); lb a comprar = MAX(lb necesarias, lb del MOQ); costo = lb × (base + recargo + transporte $/lb) ÷ cant., +\2% de margen.",
  r"quantité de lancement = qté commandée ÷ rendement cumulé (rebut par opération, par défaut \1 %) ; lb à acheter = MAX(lb nécessaires, lb du MOQ) ; coût = lb × (base + surcharge + transport $/lb) ÷ qté, +\2 % de majoration."),
 (r"^Components \+(.+)% / Consumables \+(.+)% markup\.$", r"Componentes +\1% / consumibles +\2% de margen.", r"Composants +\1 % / consommables +\2 % de majoration."),
 (r"^batch cost = MAX\(MIN \$, batch lb × \$/lb, parts × \$/pc\), \+(.+)% markup, \+ loop transport per skid \(shareable between PNs\)\.$",
  r"costo del lote = MAX(MÍN $, lb del lote × $/lb, piezas × $/pza), +\1% de margen, + flete de ida y vuelta por tarima (compartible entre PN).",
  r"coût du lot = MAX(MIN $, lb du lot × $/lb, pièces × $/pc), +\1 % de majoration, + navette par palette (partageable entre PN)."),
 (r"^App version (.+) · The modification journal is no longer displayed here \(V15\.1\) — it is still recorded and included in Export Brain JSON\.$",
  r"Versión de la App \1 · El registro de cambios ya no se muestra aquí (V15.1): se sigue guardando y se incluye al exportar el JSON del Cerebro.",
  r"Version de l’App \1 · Le journal des modifications n’est plus affiché ici (V15.1) : il est toujours enregistré et inclus dans l’export JSON du Cerveau."),
]
# Las leyendas de las donas del tablero llevan la familia y un conteo:
# "Compression Spring (3)". Una plantilla por familia, con su traducción.
for _fam in ("Compression Spring", "Tension Spring", "Torsion Spring", "Wire Form",
             "Sub-Assembly", "Miscellaneous Part", "Not specified"):
    PLANTILLAS.append((r"^%s \((\d+)\)$" % _fam.replace("-", r"\-"),
                       D[_fam][0] + r" (\1)", D[_fam][1] + r" (\1)"))
